<?php
session_start(); require_once 'db.php';
if (!isset($_SESSION['user'])) { header('Location: login.php'); exit; }
$doctors = mongoFind('doctors', [], ['sort'=>['category'=>1,'name'=>1]]);
$doctors = array_values(array_filter($doctors, static fn($doctor) => trim((string)($doctor['category'] ?? '')) !== ''));
$femaleDoctorIds = ['D002','D004','D007','D009','D012','D015','D017','D018','D019','D021','D022','D023','D024','D025','D026','D027','D028','D029','D030','D032','D034','D037','D039','D042','D047','D050','D051','D053','D055','D057','D059','D060','D061','D062','D064','D066','D068','D070'];
foreach ($doctors as &$doctor) {
    if (!isset($doctor['gender'])) {
        $doctor['gender'] = in_array($doctor['id'] ?? '', $femaleDoctorIds, true) ? 'female' : 'male';
    }
}
unset($doctor);
$appointments = mongoFind('appointments', ['status'=>['$ne'=>'Cancelled']]);
$booked=[]; foreach($appointments as $a){$booked[($a['provider_type']??'doctor').'|'.($a['provider_id']??'').'|'.($a['appointment_date']??'').'|'.($a['appointment_time']??'')]=true;}
$slots=mongoFind('appointment_slots',['provider_type'=>'doctor'],['sort'=>['slot_time'=>1]]);
$slotMap=[]; foreach($slots as $s){$providerId=$s['provider_id']??$s['doctor_id']??'';if($providerId!=='')$slotMap[$providerId][]=$s;}
$groups=[]; foreach($doctors as $d)$groups[$d['category']][]=$d;
?>
