<main class="portal-main"><section class="page-hero"><div><p class="eyebrow">DOCTOR CONSULTATION</p><h1>Find the right doctor for you.</h1><p>Choose a medical department, compare specialists, and reserve an online consultation slot.</p></div><img src="doctor-consultation.png" alt="Doctor consulting a patient"></section>
<section class="section compact"><div class="section-heading"><p class="eyebrow">1 · SELECT DEPARTMENT</p><h2>Choose a specialty</h2><p>Browse every doctor or narrow the list by department.</p></div><div class="choice-grid department-grid"><button type="button" class="choice-card department-card selected" data-filter=""><span class="choice-icon">✚</span><strong>All doctors</strong><small><?php echo count($doctors); ?> specialists</small></button><?php foreach($groups as $cat=>$ds): ?><button type="button" class="choice-card department-card" data-filter="<?php echo htmlspecialchars($cat, ENT_QUOTES, 'UTF-8'); ?>"><span class="choice-icon">✚</span><strong><?php echo htmlspecialchars($cat, ENT_QUOTES, 'UTF-8'); ?></strong><small><?php echo count($ds); ?> specialists</small></button><?php endforeach; ?></div></section>
