<section class="booking-panel" id="doctorBooking"><div><p class="eyebrow">3 · CHOOSE DATE & SLOT</p><h2>Book your consultation</h2><p id="selectedDoctor">Select a doctor to continue.</p></div><form action="book.php" method="post" class="booking-form"><input type="hidden" name="hospital" value="Aster MIMS Kannur"><input type="hidden" name="provider_type" value="doctor"><input type="hidden" name="provider_id" id="provider_id"><input type="hidden" name="provider_name" id="provider_name"><input type="hidden" name="category" id="category"><input type="hidden" name="qualification" id="qualification"><input type="hidden" name="specialty" id="specialty"><input type="hidden" name="service_name" value=""><label>Date<input type="date" name="date" id="doctor_date" required></label><label>Available online slot<select name="time" id="doctor_time" required><option value="">Select doctor first</option></select></label><label>Reason<input type="text" name="reason" placeholder="Reason for consultation"></label><label>Patient name<input type="text" name="name" value="<?php echo htmlspecialchars($_SESSION['user']['name']??''); ?>" required></label><label>Email<input type="email" name="email" value="<?php echo htmlspecialchars($_SESSION['user']['email']??''); ?>" required></label><button class="btn-primary" type="submit">Confirm Consultation</button></form></section></main>
<script>const doctors=<?php echo json_encode($doctors, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT); ?>, slotMap=<?php echo json_encode($slotMap, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT); ?>, booked=<?php echo json_encode($booked, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT); ?>;let chosen=null;function filterDoctors(category){document.querySelectorAll('.doctor-profile').forEach(card=>{card.style.display=!category||card.dataset.category===category?'flex':'none';});document.querySelectorAll('.department-card').forEach(button=>button.classList.toggle('selected',button.dataset.filter===category));document.getElementById('doctorHint').textContent=category?category+' specialists':'Showing all '+doctors.length+' doctors. Select a department to filter.';}document.querySelectorAll('.department-card').forEach(button=>button.addEventListener('click',()=>filterDoctors(button.dataset.filter)));document.querySelectorAll('.book-doctor').forEach(button=>button.addEventListener('click',()=>{chosen=doctors.find(doctor=>doctor.id===button.dataset.id);if(!chosen)return;document.getElementById('provider_id').value=chosen.id;document.getElementById('provider_name').value=chosen.name;document.getElementById('category').value=chosen.category;document.getElementById('qualification').value=chosen.qualification||'';document.getElementById('specialty').value=chosen.specialty||'';document.getElementById('selectedDoctor').textContent=chosen.name+' • '+(chosen.specialty||chosen.category);updateTimes();document.getElementById('doctorBooking').scrollIntoView({behavior:'smooth'});}));function updateTimes(){const select=document.getElementById('doctor_time');select.innerHTML='<option value="">Select an available slot</option>';if(!chosen)return;const date=document.getElementById('doctor_date').value,providerSlots=slotMap[chosen.id]||[];if(!providerSlots.length){select.innerHTML='<option value="">No online slots are configured for this doctor</option>';return;}providerSlots.forEach(slot=>{const key='doctor|'+chosen.id+'|'+date+'|'+slot.slot_time,option=document.createElement('option');option.value=slot.slot_time;if(slot.slot_status!=='Available'||booked[key]){option.disabled=true;option.textContent=slot.slot_time+' — '+(booked[key]?'Booked':'Offline visitor');}else{option.textContent=slot.slot_time+(slot.token_no?' — Token #'+slot.token_no:' — Available');}select.appendChild(option);});}document.getElementById('doctor_date').min=new Date().toISOString().slice(0,10);document.getElementById('doctor_date').onchange=updateTimes;</script></body></html>
